sys_script_fix.script:
var start = new GlideDateTime();
gs.log("Starting of PortfolioCoreTokyoUpgrade , time : "+start);
var portfolioTHelper = new PortfolioTokyoUpgradeHelper();
portfolioTHelper.updateReferenceQualifierOnPortfolio('business_unit');
portfolioTHelper.updateReferenceQualifierOnPortfolio('department');
portfolioTHelper.updateDefaultValueOnPortfolio('business_unit');
portfolioTHelper.updateDefaultValueOnPortfolio('department');
var end = new GlideDateTime();
gs.log("Ending of PortfolioCoreTokyoUpgrade , time : "+end);
gs.log("Total time taken for PortfolioCoreTokyoUpgrade in millisecs : "+(end.getNumericValue() - start.getNumericValue()));
